 const n=Math.max(0,Math.min(4,Math.round(Number(step)||0))),carriers={1727:'11·157',1728:'12³',1729:'7·13·19 = 1³+12³ = 9³+10³'},value=Object.hasOwn(carriers,carrier)?Number(carrier):1728,sigma=polarity==='PP'?'PP':'NN',glyphs=['q°','p°','b°','d°','q°'],orientations=['1','i','j','k','1'];
