function foldThreadState(step=0){const n=Math.max(0,Math.min(6,Math.round(Number(step)||0))),states=[{role:'CARRIER',register:'12³ = 1728 · h=1 · QED=0',detail:'vorhandener lokaler Cube; Torusparameter bleiben Working Pose',h:'1',qed:0},{role:'ROOT ADDRESSES',register:'(1,1) · (1,j) · (i,1) · (i,j)',detail:'symbolische Adresspaare; keine Quaternionenprodukte',h:'1',qed:0},{role:'90° / T',register:'T carrier · h=i · QED=0',detail:'Frame-Falte und Trägerrolle',h:'i',qed:0},{role:'45° / DIAGONAL',register:'δᵢⱼ=(i−j)/√2 · σ=±1 · h=j',detail:'gleiches i↔j-Trägerpaar; zwei Gegenorientierungen',h:'j',qed:0},{role:'H / T_Y TOPDECK',register:'H field · T_Y split · h=k',detail:'projiziertes Parallelogramm; getrennte View-Rollen',h:'k',qed:0},{role:'Σ GAP',register:'0.41 − 0.02 = 0.39 = 3·0.13',detail:'exaktes Dezimal-Receipt; Einheit und physikalische Deutung bleiben offen',h:'k',qed:0},{role:'RETURN',register:'1′ · h=1 · QED=1',detail:'vollständiger Anzeige-Return; offene Bindings bleiben offen',h:'1',qed:1}];return{step:n,...states[n]};}
function foldThreadUi(doc,timers={setTimeout:(fn,ms)=>setTimeout(fn,ms),clearTimeout:id=>clearTimeout(id)}){const root=doc.getElementById('fold-thread-return-conductor');if(!root)return null;const home=root.querySelector('[data-ftc-home]'),prev=root.querySelector('[data-ftc-prev]'),next=root.querySelector('[data-ftc-next]'),play=root.querySelector('[data-ftc-play]'),readout=root.querySelector('[data-ftc-readout]'),markers=[...root.querySelectorAll('[data-ftc-marker]')],listMarkers=[...root.querySelectorAll('[data-ftc-list-marker]')];let step=0,pending=[];
 function cancel(){pending.forEach(id=>timers.clearTimeout(id));pending=[];if(play)play.disabled=false;}
 function render(value=step){const state=foldThreadState(value);step=state.step;root.dataset.ftcStep=String(step);root.dataset.ftcReturn=String(state.qed);markers.forEach(marker=>marker.dataset.active=String(Number(marker.dataset.ftcMarker)===step));listMarkers.forEach(marker=>marker.dataset.active=String(Number(marker.dataset.ftcListMarker)===step));if(readout)readout.innerHTML='<small>STATE '+state.step+' · '+state.role+'</small><strong>'+state.register+'</strong><span>'+state.detail+'</span>';return state;}
 function playOnce(){cancel();step=0;render();if(play)play.disabled=true;for(let value=1;value<=6;value++)pending.push(timers.setTimeout(()=>{step=value;render();if(value===6){pending=[];if(play)play.disabled=false;}},value*380));}
 home?.addEventListener('click',()=>{cancel();step=0;render();});prev?.addEventListener('click',()=>{cancel();step=Math.max(0,step-1);render();});next?.addEventListener('click',()=>{cancel();step=Math.min(6,step+1);render();});play?.addEventListener('click',playOnce);render();return{render,playOnce,cancel,get state(){return foldThreadState(step)}};
}
